-- =============================================================================
-- 012_seed_altmeyer.sql
-- 12 real Altmeyer shops from August 2026, loaded into the Hub.
--
-- This is the validation step: if a real shop from last month cannot be
-- expressed in interactions + evaluations + observations, the schema is wrong,
-- and that is worth finding out now rather than with an application on top.
--
-- 12 shops across 11 locations, 19 people,
-- 540 scored observations.
--
-- 8 of the 45 questions being scored on these calls do NOT
-- exist in reviewer_form_points. The rubric lookup has drifted from what the
-- engine actually scores. They are created here flagged as live-data-only so
-- the drift is visible rather than silently dropped.
--
-- Requires: 001 to 011
-- =============================================================================

BEGIN;

INSERT INTO organizations (code, name, client_type, status)
VALUES ('ALT', 'Altmeyer', 'funeral_home', 'active')
ON CONFLICT (code) DO NOTHING;

-- Questions scored in production but absent from the rubric lookup.
